// Exercise library data

export type MovementPattern =
  | 'horizontal_push'
  | 'horizontal_pull'
  | 'vertical_push'
  | 'vertical_pull'
  | 'squat'
  | 'hinge'
  | 'lunge'
  | 'isolation'
  | 'carry'
  | 'rotation'
  | 'locomotion';

export interface LibraryExercise {
  id: string;
  name: string;
  bodyPart: BodyPart;
  equipment: Equipment[];
  category: ExerciseCategory;
  difficulty: 'beginner' | 'intermediate' | 'advanced';
  defaultSets: number;
  defaultReps: string;
  description: string;
  tips: string[];
  alternatives: string[];
  movementPattern?: MovementPattern;
  machineAlternatives?: string[];
}

export type BodyPart = 
  | 'chest' 
  | 'back' 
  | 'shoulders' 
  | 'legs' 
  | 'arms' 
  | 'core' 
  | 'glutes' 
  | 'full_body';

export type Equipment = 
  | 'barbell' 
  | 'dumbbell' 
  | 'bodyweight' 
  | 'machine' 
  | 'cable' 
  | 'kettlebell'
  | 'bands'
  | 'cardio';

export type ExerciseCategory = 
  | 'compound' 
  | 'isolation' 
  | 'cardio' 
  | 'plyometric'
  | 'circuit';

export type SplitType = 
  | 'full_body' 
  | 'upper_lower' 
  | 'push_pull_legs' 
  | 'bro_split'
  | 'custom';

